// Package github resolves `github` sources: the ref a manifest pinned becomes
// the commit it names, and that commit's repository archive becomes the files
// an asset installs.
//
// Names are resolved with Git and bytes are moved over HTTPS, and the split is
// the whole design. `git ls-remote` goes through whatever credential helper the
// user already configured, so a private repository resolves without harnaas
// inventing an authentication story of its own, and that path has no API rate
// limit for a CI job to exhaust. The archive endpoint is then one request per
// repository and commit rather than one request per file, which is what makes a
// skill — a directory of documents — cost the same as a rule.
//
// Resolution is kept separate from retrieval for a second reason: the lockfile
// records what was *asked for* alongside what it *resolved to*, because "the
// installed files still match the commit" and "the tag now points somewhere
// else" are two different questions and `lint` asks them separately.
package github

// remoteHost is the forge this kind speaks to, and the only place its name is
// spelled: a message, a Git remote and an archive URL all read it from here, so
// they cannot come to disagree about which host a `github` source means.
const remoteHost = "github.com"

// remoteURL is the Git remote for an `owner/repository` pair.
//
// It is built rather than taken from the manifest, which is what keeps a
// declared source from naming a host harnaas never agreed to talk to. The
// repository arrives already checked for shape by the manifest grammar, so this
// is assembly and not validation.
func remoteURL(repository string) string {
	return "https://" + remoteHost + "/" + repository + ".git"
}

package github

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"slices"
	"strings"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// A ref is not a commit. `v1.2.0` is a name in somebody else's repository, and
// the file harnaas installs has to be attributable to the object that name stood
// for on the day it ran — otherwise "did upstream move?" has no answer, and a
// lockfile recording the name records nothing.
//
// Resolution therefore happens before anything is fetched, and produces two
// facts rather than one: the commit, and whether the name that produced it can
// name a different commit tomorrow. The second is what separates a pin from a
// moving target for the lockfile and for `lint`.

// objectIDLengths are the lengths of a full Git object identifier, in the two
// hash algorithms Git has: SHA-1 and SHA-256.
//
// Only a full identifier is taken as one. An abbreviation is ambiguous by
// construction — it names whichever object it happens to be unique against
// today — and the manifest exists to pin content, so an abbreviation that grows
// a second match upstream would silently become a different install.
var objectIDLengths = []int{40, 64}

// RefResolution is what a declared ref resolved to.
type RefResolution struct {
	// Commit is the immutable commit identifier the ref named, lowercased,
	// which is the spelling Git itself produces and the lockfile records.
	Commit string

	// Mutable reports whether the ref that produced Commit can name a
	// different commit tomorrow. A branch can; a tag or a commit identifier
	// cannot.
	Mutable bool
}

// gitRunner runs git with the given arguments and returns its standard output.
//
// It is a parameter rather than a call, so the failures that matter here —
// git absent from the machine, a remote answering something that is not a
// ref listing — are exercisable without arranging for a real git to produce
// them. The same seam [source.Fetcher] uses for its size ceiling.
type gitRunner func(ctx context.Context, args ...string) ([]byte, error)

// ResolveRef resolves the ref one request's source declares to the commit it
// names, before any content is fetched.
func ResolveRef(ctx context.Context, req source.Request) (RefResolution, error) {
	return resolveRef(ctx, runGit, remoteURL(req.Source.Repository), req)
}

// resolveRef is [ResolveRef] with the git invocation and the remote as
// parameters.
func resolveRef(ctx context.Context, run gitRunner, remote string, req source.Request) (RefResolution, error) {
	ref := req.Source.Ref

	// A full commit identifier is already the answer. Asking the remote would
	// trade a round trip for a result that cannot differ from what the manifest
	// wrote, and would make a repository that is unreachable today fail a
	// resolution that needs nothing from it.
	if commit, ok := objectID(ref); ok {
		return RefResolution{Commit: commit}, nil
	}

	if ref == "" {
		return resolveDefaultBranch(ctx, run, remote, req)
	}

	// Every pattern is built with a `refs/` prefix, so no argument harnaas
	// passes can be read by git as an option — the ref arrives from a manifest
	// and is untrusted input in the same class as an archive entry's name.
	tag, peeled, branch := "refs/tags/"+ref, "refs/tags/"+ref+"^{}", "refs/heads/"+ref

	out, err := run(ctx, "ls-remote", remote, tag, peeled, branch)
	if err != nil {
		return RefResolution{}, lookupFailure(req, remote, err)
	}

	listed := listedRefs(out)

	// A tag beats a branch of the same name, which is Git's own precedence for
	// a bare name, and the peeled entry beats the tag it was peeled from: an
	// annotated tag's own object is a tag, and the commit is what an archive is
	// taken from.
	for _, candidate := range []struct {
		name    string
		mutable bool
	}{
		{name: peeled},
		{name: tag},
		{name: branch, mutable: true},
	} {
		id, listedRef := listed[candidate.name]
		if !listedRef {
			continue
		}

		commit, ok := objectID(id)
		if !ok {
			return RefResolution{}, lookupFailure(req, remote, fmt.Errorf(
				"the remote listed %q as %q, which is not a commit identifier", candidate.name, id,
			))
		}

		return RefResolution{Commit: commit, Mutable: candidate.mutable}, nil
	}

	return RefResolution{}, &UnknownRefError{
		AssetID:    req.Asset.ID,
		Repository: req.Source.Repository,
		Ref:        ref,
	}
}

// resolveDefaultBranch resolves the commit `HEAD` points at.
//
// The manifest grammar refuses a `github` source with no ref, so this is not a
// path a declared source reaches today. It is here because the source contract
// answers "what does an absent ref mean" for every kind, and the answer for a
// forge is the repository's default branch — leaving it unimplemented would make
// the first caller that has one invent a different answer.
//
// The result is mutable for the same reason a branch is: `HEAD` follows whatever
// branch the repository's owner points it at, and either can move.
func resolveDefaultBranch(ctx context.Context, run gitRunner, remote string, req source.Request) (RefResolution, error) {
	out, err := run(ctx, "ls-remote", remote, "HEAD")
	if err != nil {
		return RefResolution{}, lookupFailure(req, remote, err)
	}

	id, listed := listedRefs(out)["HEAD"]
	if !listed {
		return RefResolution{}, &UnknownRefError{
			AssetID:    req.Asset.ID,
			Repository: req.Source.Repository,
			Ref:        "HEAD",
		}
	}

	commit, ok := objectID(id)
	if !ok {
		return RefResolution{}, lookupFailure(req, remote, fmt.Errorf(
			"the remote listed HEAD as %q, which is not a commit identifier", id,
		))
	}

	return RefResolution{Commit: commit, Mutable: true}, nil
}

// listedRefs parses `git ls-remote` output into ref name to object identifier.
//
// A ref that the remote does not have is absent from the output rather than
// reported: `ls-remote` exits successfully having printed nothing, so "unknown
// ref" is a property of what came back and never of the exit status.
func listedRefs(out []byte) map[string]string {
	listed := make(map[string]string)

	for line := range strings.SplitSeq(string(out), "\n") {
		id, name, separated := strings.Cut(strings.TrimSpace(line), "\t")
		if !separated || id == "" || name == "" {
			continue
		}
		listed[name] = id
	}

	return listed
}

// objectID reports whether a string is a full Git object identifier, and
// returns it in the lowercase spelling Git itself writes.
//
// It guards two different things with one check. On the way in it decides
// whether a declared ref needs a remote lookup at all; on the way out it is what
// stops a remote's answer — untrusted text — from being pasted into an archive
// URL because it arrived on a line that looked like a ref listing.
func objectID(candidate string) (string, bool) {
	if !slices.Contains(objectIDLengths, len(candidate)) {
		return "", false
	}

	lowered := strings.ToLower(candidate)
	for _, r := range lowered {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return "", false
		}
	}

	return lowered, true
}

// lookupFailure turns a failed lookup into the diagnostic for it: git missing
// from the machine is a different problem with a different fix from a remote
// that refused, and only one of the two is about the manifest.
func lookupFailure(req source.Request, remote string, err error) error {
	if errors.Is(err, exec.ErrNotFound) {
		return &GitUnavailableError{Err: err}
	}

	return &RefLookupError{
		AssetID:    req.Asset.ID,
		Repository: req.Source.Repository,
		Ref:        req.Source.Ref,
		Remote:     remote,
		Err:        err,
	}
}

// runGit runs git and returns its standard output.
func runGit(ctx context.Context, args ...string) ([]byte, error) {
	// The executable is a constant, and every argument this package passes is
	// either a literal or a ref pattern built with a "refs/" prefix, so a ref
	// out of a manifest cannot arrive as something git reads as an option —
	// which TestARefLookupAsksOnlyForNamesUnderRefs is what holds it to.
	//nolint:gosec // G204: see above; the command is fixed and its arguments cannot be options.
	cmd := exec.CommandContext(ctx, "git", args...)

	// git must never stop to ask. harnaas's primary consumers are CI jobs and
	// coding agents, where a credential prompt is not a question anybody
	// answers — it is the run hanging until something kills it. Detaching stdin
	// closes the second route to the same outcome.
	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
	cmd.Stdin = nil

	// git puts everything a person needs on stderr, and an *exec.ExitError
	// reports nothing but a status number, so the two are folded together here
	// rather than at each call site.
	var stderr bytes.Buffer
	cmd.Stderr = &stderr

	out, err := cmd.Output()
	if err == nil {
		return out, nil
	}

	if reported := strings.Join(strings.Fields(stderr.String()), " "); reported != "" {
		return nil, fmt.Errorf("%w: %s", err, reported)
	}

	return nil, fmt.Errorf("running git: %w", err)
}

package source

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/netip"
	"net/url"
	"strings"
	"time"
)

// The transport rules live beside the source contract rather than inside the one
// kind that fetches today, because they are a property of harnaas and not of a
// kind. A second forge added later must not be able to make a request that skips
// them, and the only structural way to guarantee that is for there to be one
// fetcher and no exported way to build another.

// maxRedirects bounds a redirect chain.
//
// An archive download legitimately redirects — a forge answers with a location on
// its content host, which may itself redirect to a CDN — so the limit is not one.
// It is small because every additional hop is another destination nobody declared,
// and a chain longer than a handful is a misconfiguration or a loop rather than a
// service that needs more room.
const maxRedirects = 5

// fetchTimeout bounds a single fetch end to end, including the redirect chain and
// the body read.
//
// The context already ends a run the user interrupted; this ends one nobody is
// watching. A host that accepts a connection and then stalls forever would
// otherwise hang a CI job for as long as the job's own limit allows, which is the
// failure that looks like harnaas being broken rather than the network being.
const fetchTimeout = 5 * time.Minute

// maxResponseBytes is the ceiling on a fetched response body.
//
// Harness assets are documents, and the archive of a repository that holds them
// is measured in megabytes. The ceiling exists so that a URL serving an endless
// stream — a misconfigured proxy, an error page that never ends — fails instead
// of filling the disk, and it is generous enough that a legitimate asset
// repository never meets it. The limit on what an archive expands to is a
// separate and much smaller number, because a compressed stream this size can
// expand to far more.
const maxResponseBytes int64 = 64 << 20

// errBodyTooLarge reports a response body past the ceiling. It is a sentinel so
// [Fetcher.fetch] can tell it from a read that failed and name the limit.
var errBodyTooLarge = errors.New("response body exceeds the limit")

// destinationRule decides whether harnaas may send a request to a URL.
//
// It is a value rather than a package-level function because of what it has to
// permit under test and must never permit in production: a test server binds a
// loopback address and speaks plaintext, so a suite that could not talk to one
// could not exercise the redirect limit, the size ceiling or a single successful
// fetch. The exemption is exactly one thing, is unexported, and leaves every other
// clause of the rule in force — including on the redirect hops, which is where the
// rule earns its keep.
type destinationRule struct {
	// allowLocal permits a destination on this machine, which no production
	// fetch may have and every test server is.
	allowLocal bool
}

// check reports why harnaas will not fetch rawURL, or nil if it will.
func (r destinationRule) check(rawURL string) error {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return &InsecureDestinationError{URL: rawURL, Reason: "harnaas cannot tell where it points"}
	}

	if r.allowLocal && addressesThisMachine(parsed.Hostname()) {
		return nil
	}

	if !strings.EqualFold(parsed.Scheme, "https") {
		return &InsecureDestinationError{
			URL:    rawURL,
			Reason: fmt.Sprintf("its scheme is %q rather than https, so anyone on the path could replace what arrives", parsed.Scheme),
		}
	}
	if addressesThisMachine(parsed.Hostname()) {
		return &InsecureDestinationError{
			URL:    rawURL,
			Reason: "it addresses this machine rather than a forge",
		}
	}
	return nil
}

// addressesThisMachine reports whether host names the machine harnaas is running
// on.
//
// A source is somebody else's content, pinned by commit, and content that already
// lives on this machine is what a `local` source under .harnaas is for. So a
// destination here is either a misconfiguration or a redirect aimed at a service
// bound to loopback that never expected a request from the outside — which is the
// reason the check runs on every hop and not only on the URL harnaas built.
//
// The unspecified address is included because connecting to it reaches a local
// service on the platforms that permit it at all, and `.localhost` names because
// RFC 6761 reserves the whole label for exactly this meaning.
func addressesThisMachine(host string) bool {
	lower := strings.ToLower(host)
	if lower == "localhost" || strings.HasSuffix(lower, ".localhost") {
		return true
	}
	if addr, err := netip.ParseAddr(host); err == nil {
		return addr.IsLoopback() || addr.IsUnspecified()
	}
	return false
}

// Fetcher is the only way harnaas makes an HTTP request.
//
// One type holds every transport rule — the destination check, the redirect
// bound, the timeout and the size ceiling — so that a kind added later inherits
// all of them by having no other way to fetch anything.
type Fetcher struct {
	client *http.Client
	rule   destinationRule
}

// NewFetcher returns the fetcher production uses.
func NewFetcher() *Fetcher {
	return newFetcher(destinationRule{})
}

// newFetcher builds a fetcher under a given destination rule, which is the seam
// the suite needs in order to reach a server at all. See [destinationRule].
func newFetcher(rule destinationRule) *Fetcher {
	return &Fetcher{
		rule: rule,
		client: &http.Client{
			Timeout: fetchTimeout,
			// The destination rule runs again on every hop. Without this the
			// https-only rule is decoration: Go's default policy follows up to
			// ten redirects across schemes and hosts, and only the URL harnaas
			// built was ever checked, so an https entry point could deliver the
			// archive over plaintext from anywhere.
			CheckRedirect: func(req *http.Request, via []*http.Request) error {
				// via holds the requests already made, so it reaches the limit
				// on the hop after the last one harnaas was willing to follow —
				// which is what makes the message's count the number it
				// actually followed rather than one more than that.
				if len(via) > maxRedirects {
					return &TooManyRedirectsError{URL: via[0].URL.String(), Limit: maxRedirects}
				}
				return rule.check(req.URL.String())
			},
		},
	}
}

// Fetch retrieves the whole body at rawURL, or fails.
//
// It returns bytes rather than a stream on purpose: the size ceiling is the only
// thing standing between an endless response and the disk, and a caller handed a
// reader would have to honour that ceiling itself. Buffering also makes "no
// partial body ever reaches a caller" structural — a body that failed halfway is
// never returned at all, so a truncated archive cannot be extracted and recorded
// as a source that legitimately resolved to less than it should have.
func (f *Fetcher) Fetch(ctx context.Context, rawURL string) ([]byte, error) {
	return f.fetch(ctx, rawURL, maxResponseBytes)
}

// fetch is [Fetcher.Fetch] with the ceiling as a parameter, so the failure past
// it can be exercised without serving 64 MiB.
func (f *Fetcher) fetch(ctx context.Context, rawURL string, limit int64) ([]byte, error) {
	// Checked before the request is built, so a refused destination is a
	// destination nothing was ever sent to.
	if err := f.rule.check(rawURL); err != nil {
		return nil, err
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		return nil, &FetchError{URL: rawURL, Err: err}
	}

	resp, err := f.client.Do(req)
	if err != nil {
		return nil, refusalOrFetchError(rawURL, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, &StatusError{URL: rawURL, StatusCode: resp.StatusCode, Status: resp.Status}
	}

	body, err := readWithinLimit(resp.Body, limit)
	switch {
	case errors.Is(err, errBodyTooLarge):
		return nil, &ResponseTooLargeError{URL: rawURL, Limit: limit}
	case err != nil:
		return nil, &FetchError{URL: rawURL, Err: err}
	}
	return body, nil
}

// readWithinLimit reads r to its end, or fails reporting that it did not.
//
// One byte past the limit is read deliberately. A bare [io.LimitReader] stops at
// the limit and reports success, so an oversized body arrives truncated and
// indistinguishable from a complete one — which for an archive means a corrupt
// source whose digest is recorded as though it were the real content.
func readWithinLimit(r io.Reader, limit int64) ([]byte, error) {
	body, err := io.ReadAll(io.LimitReader(r, limit+1))
	if err != nil {
		return nil, fmt.Errorf("read response body: %w", err)
	}
	if int64(len(body)) > limit {
		return nil, errBodyTooLarge
	}
	return body, nil
}

// refusalOrFetchError surfaces a refusal the redirect policy raised as itself.
//
// The client wraps whatever [http.Client.CheckRedirect] returned in a
// [url.Error], whose own message restates the URL — the unredacted one. Returning
// harnaas's error rather than the wrapper keeps the message the user reads the
// finished diagnostic the rule wrote, and keeps the credential out of it.
func refusalOrFetchError(rawURL string, err error) error {
	var insecure *InsecureDestinationError
	if errors.As(err, &insecure) {
		return insecure
	}

	var tooMany *TooManyRedirectsError
	if errors.As(err, &tooMany) {
		return tooMany
	}

	return &FetchError{URL: rawURL, Err: err}
}

// InsecureDestinationError reports a fetch harnaas refused to make because of
// where it pointed, whether that was the URL it built or somewhere a redirect
// sent it.
type InsecureDestinationError struct {
	// URL is the refused destination, held exactly as it was written and
	// redacted where the message is built. Holding the raw value and redacting
	// at the one place it renders is what makes redaction a property of the type
	// rather than a step every caller constructing one has to remember.
	URL string

	// Reason completes "refused ... because ...", naming which clause of the
	// rule the destination failed.
	Reason string
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *InsecureDestinationError) Error() string {
	return fmt.Sprintf(
		"refusing to fetch %s because %s\n\n"+
			"harnaas fetches a source over https from a host other than this machine. "+
			"Declare a source it can reach that way, or put the content in a directory under .harnaas and declare it as a local source.",
		RedactURL(e.URL), e.Reason,
	)
}

// TooManyRedirectsError reports a chain that never arrived anywhere.
type TooManyRedirectsError struct {
	// URL is where the chain started, held raw and redacted where it renders.
	URL string

	// Limit is the number of redirects harnaas followed before stopping.
	Limit int
}

// Error states the problem and then the fix.
func (e *TooManyRedirectsError) Error() string {
	return fmt.Sprintf(
		"fetching %s followed %d redirects without arriving\n\n"+
			"The host is redirecting in a loop or through more hops than harnaas follows. "+
			"Check that the manifest names the repository directly rather than a URL that forwards to it.",
		RedactURL(e.URL), e.Limit,
	)
}

// ResponseTooLargeError reports a body past the size ceiling.
type ResponseTooLargeError struct {
	// URL is the destination that served it, held raw and redacted where it
	// renders.
	URL string

	// Limit is the ceiling in bytes, so the message states the number the
	// response has to come under rather than only that it did not.
	Limit int64
}

// Error states the problem and then the fix.
func (e *ResponseTooLargeError) Error() string {
	return fmt.Sprintf(
		"%s served more than the %d bytes harnaas reads from one source\n\n"+
			"Harness assets are documents, so a source this large is nearly always a repository that happens to contain them rather than the repository they live in. "+
			"Declare a source that holds the assets themselves.",
		RedactURL(e.URL), e.Limit,
	)
}

// StatusError reports a response harnaas will not read.
//
// It is deliberately a plain transport diagnostic: the kind that made the request
// is the only thing that knows which asset, repository and commit the URL stood
// for, so it is what turns a 404 into a message about a missing path.
type StatusError struct {
	// URL is the destination, held raw and redacted where it renders.
	URL string

	// StatusCode is the response status, kept as a number so a caller can
	// recognize the cases it has something better to say about.
	StatusCode int

	// Status is the status line, which carries the host's own wording.
	Status string
}

// Error states the problem and then the fix.
func (e *StatusError) Error() string {
	return fmt.Sprintf(
		"%s answered %s\n\n"+
			"Check that the source the manifest declares exists and is readable, then run harnaas install again.",
		RedactURL(e.URL), e.Status,
	)
}

// FetchError reports a request that produced no usable response at all.
type FetchError struct {
	// URL is the destination, held raw and redacted where it renders.
	URL string

	// Err is the underlying failure, kept so a caller can recognize a cancelled
	// run through errors.Is.
	Err error
}

// Error states the problem and then the fix.
//
// The cause is unwrapped out of its [url.Error] first. That wrapper's own message
// restates the URL unredacted, so quoting it would put back exactly what
// [RedactURL] exists to remove — and it adds nothing, since the destination is
// already the first thing this message names.
func (e *FetchError) Error() string {
	cause := e.Err

	var wrapped *url.Error
	if errors.As(cause, &wrapped) {
		cause = wrapped.Err
	}

	return fmt.Sprintf(
		"could not fetch %s: %s\n\n"+
			"Check that this machine can reach the host, then run harnaas install again.",
		RedactURL(e.URL), cause,
	)
}

// Unwrap keeps the cause reachable, so a fetch ended by an interrupt is still
// recognizable as a cancelled context rather than as a network failure.
func (e *FetchError) Unwrap() error { return e.Err }

package source

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"sync"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Registry is the set of source kinds harnaas can resolve, keyed by the name a
// manifest writes.
//
// It exists so that adding a kind is additive: the install flow asks the
// registry for a resolver and hands it a request, and contains no branch on
// which kind it got. A registry value rather than one package-level map is what
// lets a test exercise dispatch — including the failure for a kind nobody
// registered — without reaching into the set the binary itself ships.
type Registry struct {
	mu sync.Mutex

	// kinds holds each kind's constructor rather than a kind, because a kind is
	// per run. See [Kind].
	kinds map[manifest.SourceKind]NewKind
}

// Default is the registry the kinds shipped with this binary register into, and
// the one the install flow resolves through. A kind package registers itself
// from its own init, so a kind that has been linked in is a kind that works.
var Default = &Registry{}

// Register adds a kind to [Default].
func Register(name manifest.SourceKind, newKind NewKind) {
	Default.Register(name, newKind)
}

// Register adds a kind under the name a manifest writes for it.
//
// A second registration of the same name panics rather than replacing or
// ignoring the first. Registration happens during package initialization, before
// the process has read anything, so the only way to reach it is a mistake in
// harnaas's own wiring — and the two silent outcomes are a binary that resolves
// through whichever kind happened to be linked last.
func (r *Registry) Register(name manifest.SourceKind, newKind NewKind) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if r.kinds == nil {
		r.kinds = make(map[manifest.SourceKind]NewKind)
	}
	if _, registered := r.kinds[name]; registered {
		panic(fmt.Sprintf("source: kind %q is registered twice", name))
	}
	r.kinds[name] = newKind
}

// Kinds returns every registered kind name, sorted.
//
// Sorted rather than in registration order, because registration order is
// whatever the import graph happens to produce and this list is rendered into
// the error a user reads when their kind is not among them.
func (r *Registry) Kinds() []manifest.SourceKind {
	r.mu.Lock()
	defer r.mu.Unlock()

	return r.kindNamesLocked()
}

// NewResolver constructs one resolver per registered kind and returns the
// [Resolver] that dispatches to them, which is the unit of one install run.
func (r *Registry) NewResolver() *Resolver {
	r.mu.Lock()
	defer r.mu.Unlock()

	kinds := make(map[manifest.SourceKind]Kind, len(r.kinds))
	for name, newKind := range r.kinds {
		kinds[name] = newKind()
	}
	return &Resolver{kinds: kinds, registered: r.kindNamesLocked()}
}

// kindNamesLocked returns the registered names in sorted order. The caller holds
// the lock.
func (r *Registry) kindNamesLocked() []manifest.SourceKind {
	names := make([]manifest.SourceKind, 0, len(r.kinds))
	for name := range r.kinds {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

// Resolver resolves every source of one install run.
//
// It holds one live kind per registered name, so the per-run state a kind keeps
// — chiefly which repository archives it has already fetched — lives exactly as
// long as the run that built it.
type Resolver struct {
	kinds map[manifest.SourceKind]Kind

	// registered is the sorted name list, captured at construction so the error
	// for an unsupported kind lists what this run could have resolved rather
	// than what the registry holds by the time somebody reads the message.
	registered []manifest.SourceKind
}

// Resolve resolves one asset's source through the kind that owns it.
//
// The lookup happens before the kind is asked to do anything, which is what
// makes "an unsupported kind reaches no network and writes no file" a property
// of the dispatch rather than a rule each kind has to honour on its way in.
func (r *Resolver) Resolve(ctx context.Context, req Request) (*Resolved, error) {
	name := req.Kind()

	kind, registered := r.kinds[name]
	if !registered {
		return nil, &UnsupportedKindError{Kind: name, Registered: slices.Clone(r.registered)}
	}

	return kind.Resolve(ctx, req)
}

// UnsupportedKindError reports a source kind no registered kind can resolve.
//
// The manifest layer rejects a kind its grammar does not know, so reaching this
// means a kind harnaas parses but this binary cannot fetch — an older binary
// meeting a manifest written for a newer one. That is why the remedy is an
// upgrade rather than an edit, and why the error is a type: the install flow
// attributes it to the asset that carried the source.
type UnsupportedKindError struct {
	// Kind is the unresolvable kind, exactly as the manifest wrote it.
	Kind manifest.SourceKind

	// Registered is every kind this binary can resolve, sorted.
	Registered []manifest.SourceKind
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *UnsupportedKindError) Error() string {
	names := make([]string, 0, len(e.Registered))
	for _, name := range e.Registered {
		names = append(names, string(name))
	}

	return fmt.Sprintf(
		"this harnaas cannot resolve sources of kind %q\n\n"+
			"Upgrade harnaas, or declare a source of a kind it installs: %s.",
		e.Kind, strings.Join(names, ", "),
	)
}

// Package source turns a declared source into content harnaas can install.
//
// The manifest layer parses a source and resolves nothing: `github:acme/assets@v1`
// is checked for shape, and whether that repository exists, whether the ref
// points anywhere and what is at the path are all questions it deliberately does
// not ask. This package answers them, and it is the only place in harnaas that
// reaches the network or reads content out of a repository.
//
// Two things shape it. Every source kind answers the same question — given a
// parsed source and a path within it, produce the files and the provenance
// needed to record what landed — so the kinds sit behind one contract and a
// [Registry] dispatches to them by name. And a resolved source is worthless
// unless it can be re-identified later: `lint` has to answer "did somebody edit
// this?" and "has upstream moved?" independently, months after the install, from
// nothing but what was recorded. That is why a [Resolved] carries a digest per
// file and one over the source as a whole, and why the only way to obtain one is
// a constructor that computes both.
package source

import (
	"context"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Kind resolves the sources of one kind for one install run.
//
// It is created per run rather than registered as a value, because resolution is
// not stateless: a repository archive is fetched at most once per repository and
// commit per run, and the memory of what has already been fetched belongs to the
// run that did it. A kind shared across runs would either leak that memory
// between them or need a global cache to hold it.
type Kind interface {
	// Resolve produces the content and provenance for one asset's source.
	//
	// It is handed one asset rather than one `sources` entry because the unit
	// being resolved is the subtree an asset names, and because every diagnostic
	// raised here has to name the asset the author would go and edit.
	Resolve(ctx context.Context, req Request) (*Resolved, error)
}

// NewKind constructs a kind's resolver for one install run. It is what a kind
// registers, for the reason [Kind] gives.
type NewKind func() Kind

// Request is one asset's resolution: the asset being resolved and the `sources`
// entry it references.
//
// The asset travels whole rather than as the two or three fields a kind reads,
// because the fields a diagnostic needs are not the fields resolution needs — a
// message names the asset's id and its position in the manifest, and narrowing
// the request would make every kind's errors worse to keep the struct smaller.
type Request struct {
	// Asset is the manifest entry being resolved, already interpreted: its
	// reference, type and id are settled before anything is fetched.
	Asset manifest.Asset

	// Source is the parsed `sources` entry the asset references. It is the zero
	// value for the project-local form, which references no entry.
	Source manifest.Source
}

// Kind reports which source kind must resolve this request.
//
// The project-local form declares no `sources` entry and is local by definition
// of the manifest grammar, not by anything a caller decides. Answering it here,
// once, is what keeps the install flow above and the kinds below from each
// restating that rule — and from restating it differently.
func (r Request) Kind() manifest.SourceKind {
	if r.Asset.Ref.Local() {
		return manifest.SourceKindLocal
	}
	return r.Source.Kind
}

package github

import (
	"fmt"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/source"
)

// Every diagnostic here names the asset as well as the repository, because the
// person reading it is looking for the line to edit. A repository and a ref
// alone describe the failure accurately and say nothing about where it came
// from — one `sources` entry is referenced by any number of assets, and the
// manifest is what the reader has open.

// UnknownRefError reports a ref the repository does not have.
//
// It is a distinct type rather than a message because an unknown ref is the one
// ref failure that is always a manifest edit: the repository answered, harnaas
// reached it, and the name is simply not there.
type UnknownRefError struct {
	// AssetID is the asset whose source declared the ref.
	AssetID string

	// Repository is the `owner/repository` pair the manifest declared.
	Repository string

	// Ref is the ref as written, so a typo is visible in the message rather
	// than only in the file.
	Ref string
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *UnknownRefError) Error() string {
	return fmt.Sprintf(
		"the asset %q asks for %s at %q, which that repository has no tag, branch or commit for\n\n"+
			"Change the ref after @ in %s to one that exists in %s, or pin the commit identifier directly.",
		e.AssetID, e.Repository, e.Ref, manifest.FileName, e.Repository,
	)
}

// RefLookupError reports a ref lookup that could not be made at all.
//
// A repository that is private, renamed, deleted or simply unreachable all
// arrive here, and they are one diagnostic rather than four because git's own
// message is the part that tells them apart and harnaas has nothing to add to
// it. What harnaas contributes is which asset was being resolved.
type RefLookupError struct {
	// AssetID is the asset whose source was being resolved.
	AssetID string

	// Repository is the `owner/repository` pair the manifest declared.
	Repository string

	// Ref is the ref as written. It is empty where the request declared none.
	Ref string

	// Remote is the Git remote harnaas asked, held raw and redacted where the
	// message is built — the same rule the transport diagnostics follow, so
	// redaction is a property of the type rather than a step a caller
	// constructing one has to remember.
	Remote string

	// Err is git's own failure, kept so a caller can still recognize a
	// cancelled run through errors.Is.
	Err error
}

// Error states the problem and then the fix.
func (e *RefLookupError) Error() string {
	return fmt.Sprintf(
		"could not resolve %s for the asset %q against %s: %s\n\n"+
			"Check that the repository exists and that this machine can read it — a private repository is resolved with the Git credentials already configured on this machine — then run harnaas install again.",
		e.describeRef(), e.AssetID, source.RedactURL(e.Remote), e.Err,
	)
}

// Unwrap keeps git's failure inspectable, which is what lets an interrupted run
// still be recognized as a cancellation rather than as a repository problem.
func (e *RefLookupError) Unwrap() error { return e.Err }

// describeRef names what was being resolved, which is a ref where the manifest
// declared one and the default branch where it did not.
func (e *RefLookupError) describeRef() string {
	if e.Ref == "" {
		return "the default branch of " + e.Repository
	}
	return fmt.Sprintf("%q in %s", e.Ref, e.Repository)
}

// GitUnavailableError reports that harnaas could not run git at all.
//
// It is separate from every other lookup failure because it is the one that is
// not about the manifest, the network or the repository: nothing the author
// could write in `harnaas.json` would fix it, so a message pointing at the file
// would send them to edit a file that is already correct.
type GitUnavailableError struct {
	// Err is the failure that reported git missing, kept for logs and for a
	// caller matching on exec.ErrNotFound.
	Err error
}

// Error states the problem and then the fix.
func (e *GitUnavailableError) Error() string {
	return fmt.Sprintf(
		"harnaas resolves a %s source's ref by running git, which is not installed on this machine\n\n"+
			"Install git and run harnaas install again, or pin each %s source to a full commit identifier, which needs no lookup.",
		manifest.SourceKindGitHub, manifest.SourceKindGitHub,
	)
}

// Unwrap keeps the underlying lookup failure inspectable.
func (e *GitUnavailableError) Unwrap() error { return e.Err }

