		path    string
	}{
		{
			name:    "unknown ref",
			fetcher: &countingFetcher{body: archive},
			path:    "skills/review",
		},
		{
			name:    "retrieval refused",
			listing: tagListing,
			fetcher: &countingFetcher{err: errors.New("the host refused")},
			path:    "skills/review",
